from pathlib import Path
import json,base64,hashlib
from PIL import Image,ImageDraw,ImageFont
root=Path(__file__).parent
p=root/'public';e=p/'evidence'
def caesar(s,n):
 return ''.join(chr((ord(c)-65+n)%26+65) if 'A'<=c<='Z' else c for c in s)
def b64(s): return base64.b64encode(s.encode()).decode()
missions=[]
def m(id,level,title,kind,minutes,brief,steps,evidence,answer,hints,explain,tool=None,asset=None):
 missions.append(dict(id=id,level=level,title=title,kind=kind,minutes=minutes,brief=brief,steps=steps,evidence=evidence,answer=answer,hints=hints,explain=explain,tool=tool,asset=asset))
m('b1','beginner','Your first flag','Orientation',3,'Rogue 9 has sealed the canal gate. Moss needs a technician who can follow evidence. A flag is the answer token you recover in a CTF (Capture the Flag).',['Read the dispatch below.','Copy the complete flag, including HACK{ and }, into the answer box.','Write a short evidence note after each solve.'], 'DISPATCH / MOSS\nTraining token: HACK{CLOCK_IN}\nFlags use braces { } and underscores _ instead of spaces.','HACK{CLOCK_IN}',['Look for HACK followed by braces.','The training token is printed in the dispatch.','Enter HACK{CLOCK_IN}.'],'A flag proves you found a specific clue. In real help-desk work, your evidence and explanation matter more than a guessed answer.')
m('b2','beginner','Scrambled transmission','Cryptography',6,'A message was shifted three letters forward: A became D. Reverse that shift to recover it. This is a Caesar cipher, a simple form of encryption.',['Open the Caesar tool in the Field Kit.','Paste the entire transmission and choose Decode with shift 3.','Submit the recovered flag.'],caesar('HACK{SIGNAL_FOUND}',3),'HACK{SIGNAL_FOUND}',['Decode moves letters backward. Braces and underscores do not move.','Set shift to 3 and select Decode.','KDFN becomes HACK. The answer is HACK{SIGNAL_FOUND}.'],'Encryption changes a message using a rule and key. The shift value is the key here. Caesar is easy to break and is not secure modern encryption.', 'caesar')
m('b3','beginner','Behind the sign','Web investigation',6,'A maintenance sign looks ordinary. Its HTML source contains a comment left by a technician. HTML describes a webpage; comments are notes that are not displayed.',['Open the maintenance sign using the evidence link.','Return here and select “View supplied HTML” below to inspect its source. You may also use browser View Page Source.','Find the comment containing the flag.'],None,'HACK{LOOK_BEHIND}',['HTML comments begin with <!-- and end with -->.','Search the supplied HTML for “technician”.','The comment says HACK{LOOK_BEHIND}.'],'A browser receives HTML even when some parts are not displayed. Anything delivered to the browser can be inspected. HTML comments are not a safe place for passwords.',asset='maintenance.html')
m('b4','beginner','Which door opened?','Network evidence',7,'A fictional gate log records device addresses and requests. HTTP status 403 means refused; 200 means the request succeeded. Find the source IP of the successful /gate/open request.',['Read every column: time, source IP, path, status.','Find the row where BOTH path is /gate/open AND status is 200.','Wrap that row’s source IP in HACK{...}.'], 'TIME      SOURCE IP       PATH           STATUS\n09:10:01  192.168.1.21    /status        200\n09:10:05  192.168.2.44    /gate/open     403\n09:10:09  192.168.1.37    /gate/open     200\n09:10:12  192.168.1.21    /help          200','HACK{192.168.1.37}',['A successful /status request is not a successful gate opening.','Match the /gate/open path and 200 status on the same row.','The matching source is 192.168.1.37. Enter HACK{192.168.1.37}.'],'An IP address helps identify a source in this log. It does not prove who was at the keyboard or that this device was malicious. Investigations need context and corroboration.')
m('b5','beginner','The poster has a secret','Steganography',8,'The gate poster contains text with almost the same color as its background. Steganography hides the existence of a message. Reveal the faint text.',['Look at the poster below.','Open the Image Reveal tool and increase contrast.','Read and submit the hidden flag.'],None,'HACK{GATE_ONLINE}',['The message is near the bottom of the poster.','Increase contrast to its highest setting.','The poster reveals HACK{GATE_ONLINE}.'],'Steganography hides a message inside something else. This poster uses faint pixels; later missions hide data inside pixel bits. Encryption hides meaning, while steganography hides presence.','reveal','poster.png')
m('i1','intermediate','The mislabeled envelope','Encoding',6,'An intercepted envelope says “encrypted.” The payload is actually Base64, an encoding used to represent bytes as printable text. Decode it.',['Use the Base64 tool.','Decode the supplied payload.','Submit the result, then explain why Base64 is not encryption.'],b64('HACK{ENCODING_IS_NOT_ENCRYPTION}'),'HACK{ENCODING_IS_NOT_ENCRYPTION}',['Base64 often contains uppercase/lowercase letters, digits, +, /, and = padding.','Choose Base64 → Decode.','Decoded: HACK{ENCODING_IS_NOT_ENCRYPTION}.'],'Base64 needs no secret key. Anyone with the text can reverse it. Encoding is not a way to protect a password.','base64')
m('i2','intermediate','Follow the name','DNS + addressing',7,'DNS maps names to records, including IPv4 addresses (A records). Find canal.hackville.test, then identify that address in the traffic table. All names and logs are fictional.',['Resolve the exact hostname using the DNS table.','Match that IP to a destination in the flow table.','Use the matching flow’s destination port as HACK{PORT_NUMBER}.'],'DNS RECORDS\ncanal.hackville.test   A  192.168.1.80\narchive.hackville.test A  192.168.1.81\n\nFLOWS (destination port identifies the service endpoint)\nSOURCE         DESTINATION    DEST PORT  SERVICE\n192.168.1.22   192.168.1.81   443        HTTPS\n192.168.1.22   192.168.1.80   8080       Gate web app\n192.168.1.23   192.168.1.53   53         DNS','HACK{8080}',['Use canal, not archive.','canal resolves to .80. Find the flow to .80.','The destination port is 8080. Enter HACK{8080}.'],'DNS answers a name-to-record question. An IP selects an address; a transport port identifies an endpoint for a service. A port alone does not prove the actual application.')
m('i3','intermediate','Bytes from the console','Hex + commands',6,'A simulated console printed hexadecimal bytes. Hexadecimal is base 16; two hex digits represent one byte. Use the Hex tool to recover the text.',['Read the command guide below. No real terminal is needed.','Copy only the hex bytes into the Hex tool.','Decode and submit the recovered flag.'],'SIMULATED CONSOLE\n$ cat clue.hex\n48 41 43 4b 7b 42 59 54 45 53 5f 54 45 4c 4c 5f 53 54 4f 52 49 45 53 7d\n\nCOMMAND GUIDE\n$ = a prompt marker; do not type it.\nLinux/macOS: cat clue.hex prints the file contents.\nWindows PowerShell: Get-Content clue.hex prints the file contents.\nclue.hex = the filename, not a command.','HACK{BYTES_TELL_STORIES}',['Copy the line beginning 48 41.','48 is H, 41 is A, 43 is C, 4b is K.','Decoded: HACK{BYTES_TELL_STORIES}.'],'Hex is a readable representation of bytes, not encryption. cat and Get-Content display a file; they do not automatically decode its hexadecimal contents.','hex')
m('i4','intermediate','A bit beneath the surface','Pixel steganography',9,'This PNG looks like a normal signal badge. A message was hidden in the least significant bit (LSB) of each red pixel channel, starting at the top-left and moving across each row.',['Open the Pixel Reader tool.','Choose “Read signal badge”. It reads the red LSBs in groups of eight bits until a zero byte.','Record what changed compared with the faint-text poster; submit the flag.'],None,'HACK{PIXELS_HAVE_LAYERS}',['Each color channel is a number from 0 to 255. Its last binary bit can store one hidden bit.','Use the Pixel Reader, not the contrast slider.','The extracted message is HACK{PIXELS_HAVE_LAYERS}.'],'A one-step change in a red value is difficult to see. Eight hidden bits form one byte. Our reader is designed for this exact format; it is not a universal steganography detector.','pixels','signal.png')
m('i5','intermediate','Evidence before accusation','Incident correlation',8,'A gate token was fetched, then used. Identify the source IP that performed BOTH requests with the same request ID. A successful page view alone is not enough.',['Match request ID G7 across both tables.','Check source IP and status.','Submit the correlated source address.'],'TOKEN LOG\nTIME     SOURCE IP       REQUEST ID  ACTION       STATUS\n10:00:01 192.168.1.18    B2          fetch-token  200\n10:00:04 192.168.2.44    G7          fetch-token  200\n10:00:05 192.168.1.18    C3          fetch-token  403\n\nGATE LOG\nTIME     SOURCE IP       REQUEST ID  ACTION       STATUS\n10:00:10 192.168.1.18    B2          open-gate    403\n10:00:11 192.168.2.44    G7          open-gate    200\n10:00:12 192.168.1.99    Z9          view-home    200','HACK{192.168.2.44}',['Correlate using the request ID, not just the order of events.','G7 appears with two successful actions.','Both G7 records use 192.168.2.44. Enter HACK{192.168.2.44}.'],'Correlating identifiers and timestamps creates a stronger explanation than selecting an unusual IP. This is the observed source in the supplied evidence, not proof of a person’s identity.')
m('a1','advanced','Two wrappers','Layered decoding',8,'Rogue 9 nested a Caesar-shifted flag inside Base64. Reverse the outer encoding first, then reverse the inner cipher. The shift key is the number of bits in one byte.',['Determine the key from the byte clue.','Decode Base64, then Caesar-decode the result with that key.','Save the exact recovered flag; you will reuse its inner word in the final mission.'],b64(caesar('HACK{NIGHTSHIFT}',8)),'HACK{NIGHTSHIFT}',['There are 8 bits in a byte.','First Base64-decode; then Caesar-decode by 8.','The recovered flag is HACK{NIGHTSHIFT}.'],'Order matters when transformations are layered. These reversible toy transformations teach process; layering weak methods does not make them secure.','base64')
m('a2','advanced','Find the crossed wire','Subnet reasoning',8,'Use the supplied /24 rule to audit three endpoint settings. With a /24 mask (255.255.255.0), devices on the same local IPv4 subnet share the first three octets. Find the device whose configured gateway is outside its subnet.',['Apply the /24 rule to each device and gateway.','Select the one misconfigured endpoint.','Submit its device name inside HACK{...}.'],'ALL ENDPOINTS USE /24\nDEVICE    IP ADDRESS       DEFAULT GATEWAY\nRELAY_A   192.168.1.40     192.168.1.1\nRELAY_B   192.168.2.41     192.168.1.1\nRELAY_C   192.168.2.42     192.168.2.1\n\nAn octet is one of the four dot-separated numbers.\nThe default gateway is the router an endpoint normally uses to reach other networks.','HACK{RELAY_B}',['Compare each IP’s first three numbers with its gateway’s first three numbers.','RELAY_B is on 192.168.2.0/24, but its gateway is on 192.168.1.0/24.','Enter HACK{RELAY_B}.'],'With these ordinary /24 endpoint settings, the gateway must be reachable on the local subnet. This conclusion applies to the supplied configuration, not to every possible routing design.')
original='MOSS: KEEP THE CANAL OPEN'
digest=hashlib.sha256(original.encode()).hexdigest()
m('a3','advanced','Trust the fingerprint','File integrity',8,'Only one candidate exactly matches the trusted SHA-256 digest. A cryptographic hash maps input bytes to a fixed-length fingerprint. Compare the candidates; punctuation and spaces matter.',['Copy one candidate at a time into the SHA-256 tool, without its label.','Match the output to the trusted digest. Do not add a newline.','Submit HACK{A}, HACK{B}, or HACK{C}.'],f'TRUSTED SHA-256\n{digest}\n\nA: MOSS: KEEP THE CANAL CLOSED\nB: MOSS: KEEP THE CANAL OPEN\nC: MOSS: KEEP THE CANAL OPEN!','HACK{B}',['Hash only the sentence after the label and space.','Candidate B has no final punctuation.','The trusted digest matches candidate B. Enter HACK{B}.'],'A matching trusted hash supports integrity: these bytes match the reference. A hash alone does not identify an author or guarantee safety. The reference itself must come from a trusted source.','hash')
m('a4','advanced','Rebuild the timeline','Network + HTTP',10,'The public IP in an alert is a shared NAT address. Identify the internal device using a source-port mapping AND the matching HTTP request. NAT lets multiple internal devices share one public address.',['Match the alert’s public source port and timestamp to the NAT table.','Check the corresponding internal device in the request table.','Submit the internal IP supported by both records.'],'ALERT\n11:04:12 source 203.0.113.8:51002 → 198.51.100.20:443\nrequest ID R42; path /gate/override; status 200\n\nNAT TABLE (active at 11:04:12)\nINTERNAL SOURCE        PUBLIC SOURCE\n192.168.1.18:60100     203.0.113.8:51001\n192.168.2.44:60200     203.0.113.8:51002\n192.168.2.45:60300     203.0.113.8:51003\n\nHTTP REQUEST LOG\nTIME     INTERNAL IP     ID   PATH            STATUS\n11:04:12 192.168.2.44    R42  /gate/override  200\n11:04:12 192.168.2.45    R43  /gate/override  403\n11:04:13 192.168.1.18    R44  /status         200\n\naddress:port = an IP address followed by a transport port.','HACK{192.168.2.44}',['All devices share the public IP; the translated source port distinguishes the mappings.','Public source port 51002 maps to 192.168.2.44:60200.','R42 confirms 192.168.2.44. Enter HACK{192.168.2.44}.'],'A shared public IP is not enough to attribute traffic to a device. Timestamped NAT mappings plus request evidence support a more precise conclusion. Attribution to a human still needs more evidence.')
m('a5','advanced','The final handoff','Combined investigation',10,'The final badge stores a Base64 payload in red-channel LSBs. Decode it to reveal the assembly rule. Recover the earlier word, internal IP, and service port, then assemble the final flag.',['Use Pixel Reader → Read final badge.','Base64-decode the extracted text to reveal the assembly rule.','Use your earlier case records. Submit the complete assembled flag and export your handoff.'],None,'HACK{NIGHTSHIFT_192.168.2.44_8080}',['Pixel extraction gives Base64 text. Decode that text before assembling anything.','Use A1’s inner word, A4’s internal IP, and I2’s destination port, in that order.','Enter HACK{NIGHTSHIFT_192.168.2.44_8080}.'],'You combined hidden bytes, encoding, cryptography, and network evidence. The final product is a defensible handoff: what you observed, how you interpreted it, and which evidence supports your conclusion.','pixels','final.png')
# Generate actual bit-bearing PNG evidence.
def badge(name,payload):
 im=Image.new('RGB',(720,280),(9,20,30));d=ImageDraw.Draw(im)
 for x in range(0,720,30): d.line((x,0,x,280),fill=(20,40,50))
 for y in range(0,280,30): d.line((0,y,720,y),fill=(20,40,50))
 font='/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
 f=ImageFont.truetype(font,32);s=ImageFont.truetype(font,17)
 d.rectangle((35,35,685,245),outline=(52,230,205),width=3)
 d.text((60,70),'CHATTY HACKVILLE // SIGNAL',font=f,fill=(235,245,255))
 d.text((60,135),'RED CHANNEL / LSB / ROW ORDER',font=s,fill=(255,55,147))
 d.text((60,180),'The surface is only the beginning.',font=s,fill=(150,178,191))
 bits=''.join(f'{b:08b}' for b in payload.encode()+b'\0');px=im.load()
 for idx,b in enumerate(bits):
  x=idx%im.width;y=idx//im.width;r,g,bl=px[x,y];px[x,y]=((r&254)|int(b),g,bl)
 im.save(e/name)
badge('signal.png','HACK{PIXELS_HAVE_LAYERS}')
badge('final.png',b64('ASSEMBLE: HACK{A1_INNER_WORD_A4_INTERNAL_IP_I2_PORT}'))
im=Image.new('RGB',(900,360),(8,14,24));d=ImageDraw.Draw(im)
f=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',42)
s=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',28)
d.text((45,45),'CANAL GATE // OFFLINE',font=f,fill=(255,55,147));d.text((45,120),'A quiet signal is still a signal.',font=s,fill=(130,180,190))
d.rectangle((30,220,870,335),fill=(14,14,14));d.text((55,252),'HACK{GATE_ONLINE}',font=s,fill=(19,19,19));im.save(e/'poster.png')
(e/'maintenance.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><title>Canal Maintenance</title><style>body{background:#09131f;color:#eaf6ff;font:22px monospace;padding:10vw}strong{color:#36e6cd}</style><h1>CANAL MAINTENANCE</h1><p>Gate access is suspended. Technician inspection required.</p><!-- technician handoff: HACK{LOOK_BEHIND} --><p><strong>Inspect the evidence. Follow the signal.</strong></p><p>Return to your Ghost Runner tab to submit.</p></html>''')
(p/'missions.js').write_text('const MISSIONS = '+json.dumps(missions,indent=2)+';\n')
(root/'teacher'/'MOSS_ANSWER_GUIDE.md').write_text('# Ghost Runner — Moss guide\n\n## Run it\nBeginner: approximately 30 minutes, then 3–5 minutes to export and submit the handoff. Intermediate: about 35–45 minutes. Advanced: about 45–60 minutes. Times are estimates; advanced students may skip directly to a level. A5 reuses A1, A4 and I2; all missions remain accessible for reference.\n\nUse pairs: one investigator, one evidence recorder; swap halfway. Students need a browser. No accounts, installs, API keys, or paid tools. After joining with initials, verified mission progress appears on the shared leaderboard. Evidence notes stay in the browser unless students download and submit their handoff in your LMS. The leaderboard shows solved mission IDs, not written notes.\n\nRequire an evidence note for each mission (observation + reasoning). Hints do not subtract points. For a quick formative check: 1 point per recovered flag + 1 per supported explanation, 10 points per level. No live targets are scanned or attacked. Logs are fictional.\n\nPractice progress and notes save locally when browser storage is available. Initials and solved-mission IDs also save online when the leaderboard is connected. Shared devices: export first, copy the private recovery code if needed, then use End shift on this device. Use Reset only in unsigned practice mode. The page warns if saving is unavailable. Do not treat local completion as a secure assessment: a static CTF exposes source and answer logic to inspection. This is a learning activity.\n\nKeep this teacher folder outside the deployed public directory.\n\n## Solutions\n\n'+'\n\n'.join(f'### {x["id"].upper()} — {x["title"]}\nAnswer: `{x["answer"]}`\n\nRoute: {" ".join(x["steps"])}\n\nFinal hint: {x["hints"][-1]}\n\nLearning: {x["explain"]}' for x in missions)+'\n')
(root/'server').mkdir(exist_ok=True)
(root/'server/answers.json').write_text(json.dumps({m['id']:m['answer'] for m in missions},indent=2)+'\n')
print('Wrote',len(missions),'missions + 4 evidence assets + server answer map')
